    "leanExcerpts": {
      "lean-main-theorem": "/-- Every finite bridgeless graph has a cycle double cover. -/\ntheorem cycleDoubleCover_of_bridgeless\n    {V E : Type u} [Fintype V] [Fintype E]\n    [DecidableEq V] [DecidableEq E]\n    (G : FiniteGraph V E) (hb : G.Bridgeless) :\n    Nonempty G.CycleDoubleCover := by\n  let R : G.RotationSystem := G.rotationSystemOfBridgeless hb\n  let K : CubicGraph G.ExpandedVertex G.ExpandedEdge := G.cubicExpansion R\n  have hK : K.toFiniteGraph.Bridgeless := by\n    simpa [K] using G.cubicExpansion_bridgeless R hb\n  obtain ⟨gamma⟩ := K.toFiniteGraph.jaegerKilpatrickEightFlow hK\n  exact cycleDoubleCover_of_gammaFlow G R gamma",
      "lean-gamma-flow": "/-- A nowhere-zero Gamma-flow on a cubic expansion supplies a cycle double cover. -/\ntheorem cycleDoubleCover_of_gammaFlow\n    (G : FiniteGraph V E) (R : G.RotationSystem)\n    (gamma : (G.cubicExpansion R).toFiniteGraph.NowhereZeroFlow Gamma) :\n    Nonempty G.CycleDoubleCover := by\n  let K := G.cubicExpansion R\n  let cubicCover := cubic_even_double_cover K (K.gammaFlowOfNowhereZero gamma)\n  let projected := G.projectEvenDoubleCover R cubicCover\n  exact ⟨projected.toCycleDoubleCover⟩",
      "lean-local-pair-parity": "/-- The finite local parity fact used at a cubic vertex. -/\ntheorem local_pair_parity :\n    ∀ (x y t s : Gamma),\n      x ≠ 0 → y ≠ 0 → x ≠ y →\n      pairIndicator t x s +\n      pairIndicator (t + x) y s +\n      pairIndicator t (x + y) s = 0 := by\n  decide",
      "lean-compatibility": "theorem compatibility_solvable\n    (G : CubicGraph V E) (f : GammaFlow G) :\n    compatibilityRhs G f ∈ LinearMap.range (compatibilityMap G f) := by\n  apply mem_range_of_dual_obstructions_vanish\n  intro φ hφ\n  let η : E → Module.Dual F₂ Gamma := coordinateFunctional φ\n  -- Local constraints on η are derived here.\n  -- The local dual identity turns each vertex term into a parity count.\n  simp_rw [hcontrib, hlocal]\n  rw [← G.sum_edgeEnds_eq_sum_vertexSlots\n    (fun e _ ↦ functionalNonzero (η e))]\n  simp [show (2 : F₂) = 0 by decide]",
      "lean-cubic-labeling": "noncomputable def cubic_labeling\n    (G : CubicGraph V E) (f : GammaFlow G) : CubicLabeling G f := by\n  let x := Classical.choose (compatibility_solvable G f)\n  have hx : compatibilityMap G f x = compatibilityRhs G f := by\n    simpa [x] using Classical.choose_spec (compatibility_solvable G f)\n  let t : V → Gamma := x.1\n  let ε : E → F₂ := x.2\n  let p : E → Gamma := fun e ↦\n    t (G.endAt e 0) + localBase G f (G.endAt e 0) e\n  -- Endpoint agreement and vertex parity follow.\n  refine ⟨p, ?_⟩\n  intro v s\n  -- Reduced to local_pair_parity.\n  exact local_pair_parity _ _ _ _ ‹_› ‹_› ‹_›",
      "lean-even-double-cover": "noncomputable def cubic_even_double_cover\n    (G : CubicGraph V E) (f : GammaFlow G) : IndexedEvenDoubleCover G := by\n  let P := cubic_labeling G f\n  refine\n    { member := fun s e ↦ pairIndicator (P.base e) (f.val e) s\n      vertexEven := ?_\n      coveredTwice := ?_ }\n  · intro s v\n    exact P.vertexParity v s\n  · intro e\n    exact pairIndicator_card (P.base e) (f.val e) (f.nowhereZero e)",
      "lean-cycle-decomposition": "theorem decompose_even_edge_set\n    (F : Finset E) (hF : G.IsEvenEdgeSet F) :\n    ∃ L : List G.Cycle, ∀ e : E,\n      (L.filter fun C ↦ e ∈ C.edges).length = if e ∈ F then 1 else 0 := by\n  classical\n  revert hF\n  refine Finset.strongInductionOn F ?_\n  intro F ih hF\n  by_cases hne : F.Nonempty\n  · by_cases hmin : ∀ D, D.Nonempty → D ⊆ F → G.IsEvenEdgeSet D → D = F\n    · -- F itself is a minimal even set: one cycle.\n      exact ⟨[⟨F, hne, hF, hmin⟩], by simp⟩\n    · -- Split off a smaller even set and recurse.\n      obtain ⟨D, hDne, hDF, hDeven, hDproper⟩ := hmin\n      -- Inductive bookkeeping continues in the full source.\n  · exact ⟨[], by simp_all⟩",
      "lean-cover-to-cycles": "noncomputable def IndexedEvenDoubleCover.toCycleDoubleCover\n    (C : G.IndexedEvenDoubleCover) : G.CycleDoubleCover := by\n  classical\n  have hex : ∀ s : Gamma, ∃ L : List G.Cycle,\n      ∀ e : E, (L.filter fun Z ↦ e ∈ Z.edges).length =\n        if e ∈ C.support G s then 1 else 0 := by\n    intro s\n    exact G.decompose_even_edge_set _ (C.support_even G s)\n  choose pieces hpieces using hex\n  refine { cycles := Finset.univ.toList.flatMap pieces, coveredTwice := ?_ }\n  intro e\n  simpa [C.support] using C.coveredTwice e"
    },
